static RD_BOOL add(const char*k,const char*v){int i;WCHAR w[256];memset(w,0,sizeof(w));if(!k||!*k||strlen(k)>=64||strlen(v)>=256||!MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,v,-1,w,256))return False;for(i=0;i<item_count;i++)if(!strcmp(items[i].key,k))break;if(i==item_count){if(item_count>=192)return False;item_count++;STRNCPY(items[i].key,k,sizeof(items[i].key));}STRNCPY(items[i].utf8,v,sizeof(items[i].utf8));memcpy(items[i].wide,w,sizeof(w));return True;}
static void unescape(char*s){char*r=s,*w=s;while(*r){if(r[0]=='\\'&&r[1]=='n'){*w++='\n';r+=2;}else if(r[0]=='\\'&&r[1]=='\\'){*w++='\\';r+=2;}else *w++=*r++;}*w=0;}
static int load_file(const char*dir,const char*l){char path[MAX_PATH*2],line[512],*out,*eq;FILE*f;int loaded=0;snprintf(path,sizeof(path),"%s\\%s.lang",dir,l);f=fopen(path,"rb");if(!f)return -1;while(fgets(line,sizeof(line),f)){out=line;if((unsigned char)out[0]==0xef&&(unsigned char)out[1]==0xbb&&(unsigned char)out[2]==0xbf)out+=3;out[strcspn(out,"\r\n")]=0;if(!*out||*out=='#')continue;eq=strchr(out,'=');if(!eq||eq==out){fclose(f);return -1;}*eq++=0;unescape(eq);if(!add(out,eq)){fclose(f);return -1;}loaded++;}fclose(f);return loaded;}
static void load_embedded(void){int i;item_count=0;for(i=0;fallback[i][0];i++)add(fallback[i][0],fallback[i][1]);}
RD_BOOL win32_i18n_load_from_directory(const char*l,const char*dir){char wanted[16];load_embedded();load_file(dir,"en-US");STRNCPY(wanted,l&&*l?l:"en-US",sizeof(wanted));if(!_stricmp(wanted,"en-US")){STRNCPY(current_locale,"en-US",sizeof(current_locale));return True;}if(load_file(dir,wanted)<0){load_embedded();load_file(dir,"en-US");STRNCPY(current_locale,"en-US",sizeof(current_locale));return False;}STRNCPY(current_locale,wanted,sizeof(current_locale));return True;}
void win32_i18n_load(const char*l){char module[MAX_PATH],dir[MAX_PATH*2],*slash;GetModuleFileNameA(NULL,module,sizeof(module));slash=strrchr(module,'\\');if(slash)*slash=0;snprintf(dir,sizeof(dir),"%s\\resources\\lang",module);if(!win32_i18n_load_from_directory(l,dir))win32_i18n_load_from_directory(l,"resources\\lang");}
const char*win32_i18n_get(const char*k){int i;if(!item_count)win32_i18n_load("en-US");for(i=0;i<item_count;i++)if(!strcmp(items[i].key,k))return items[i].utf8;return k;}
const WCHAR*win32_i18n_get_w(const char*k){static WCHAR missing[64];int i;if(!item_count)win32_i18n_load("en-US");for(i=0;i<item_count;i++)if(!strcmp(items[i].key,k))return items[i].wide;MultiByteToWideChar(CP_UTF8,0,k,-1,missing,64);return missing;}
const char*win32_i18n_locale(void){return current_locale;}
#else
void win32_i18n_load(const char*l){UNUSED(l);}RD_BOOL win32_i18n_load_from_directory(const char*l,const char*d){UNUSED(l);UNUSED(d);return False;}const char*win32_i18n_get(const char*k){return k;}const char*win32_i18n_locale(void){return "en-US";}
#endif
